def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find all prime factors
    prime_factors = []
    for i in range(2, a + 1):
        if a % i == 0 and is_prime(i):
            prime_factors.append(i)

    # Check if the number is product of exactly 3 primes
    if len(prime_factors) != 3:
        return False

    # Check if the product equals a
    product = prime_factors[0] * prime_factors[1] * prime_factors[2]
    return product == a

def get_row(lst, x):
    coordinates = []

    for row_idx, row in enumerate(lst):
        for col_idx, value in enumerate(row):
            if value == x:
                coordinates.append((row_idx, col_idx))

    # Sort by row ascending, then by column descending
    coordinates.sort(key=lambda coord: (coord[0], -coord[1]))

    return coordinates

def encode(message):
    vowels = 'aeiou'
    result = []

    for char in message:
        if char.isalpha():
            # Swap case
            if char.islower():
                swapped_char = char.upper()
            else:
                swapped_char = char.lower()

            # Replace vowels
            if swapped_char.lower() in vowels:
                # Find the vowel's position and get the one 2 places ahead
                vowel_index = vowels.index(swapped_char.lower())
                new_vowel = vowels[(vowel_index + 2) % len(vowels)]
                # Preserve the original case
                if swapped_char.isupper():
                    result.append(new_vowel.upper())
                else:
                    result.append(new_vowel)
            else:
                result.append(swapped_char)
        else:
            result.append(char)

    return ''.join(result)

def even_odd_palindrome(n):
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def move_one_ball(arr):
