def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    # Split the string into individual letters
    letters = test.split()

    # Count occurrences of each letter
    count_dict = {}
    for letter in letters:
        count_dict[letter] = count_dict.get(letter, 0) + 1

    # Find the maximum count
    max_count = max(count_dict.values())

    # Return all letters with the maximum count
    return {letter: count for letter, count in count_dict.items() if count == max_count}

def max_fill(grid, capacity):
    import math

    total_water = 0

    # Count total units of water in all wells
    for row in grid:
        total_water += sum(row)

    # If there's no water, no need to lower buckets
    if total_water == 0:
        return 0

    # Calculate number of bucket operations needed
    # Each operation can extract 'capacity' units of water
    return math.ceil(total_water / capacity)

def select_words(s, n):
    if not s:
        return []

    vowels = set('aeiouAEIOU')
    words = s.split()
    result = []

    for word in words:
        consonant_count = sum(1 for char in word if char.isalpha() and char not in vowels)
        if consonant_count == n:
            result.append(word)

    return result

def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Try both possible concatenations
    concat1 = lst[0] + lst[1]
    concat2 = lst[1] + lst[0]

    if is_balanced(concat1) or is_balanced(concat2):
        return 'Yes'
    else:
        return 'No'

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    if ' ' in txt:
        return txt.split(' ')
    elif ',' in txt:
        return txt.split(',')
    else:
        count = 0
        for char in txt:
            if char.islower():
                order = ord(char) - ord('a')
                if order % 2 == 1:
                    count += 1
        return count

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def convert_to_float(val):
        if isinstance(val, (int, float)):
            return float(val)
        elif isinstance(val, str):
            # Replace comma with dot for decimal representation
            normalized = val.replace(',', '.')
            return float(normalized)
        else:
            raise ValueError("Unsupported type")

    def convert_to_original_type(val, original_val):
        if isinstance(original_val, int):
            return int(val)
        elif isinstance(original_val, float):
            return float(val)
        else:  # string
            return original_val

    # Convert both values to float for comparison
    a_float = convert_to_float(a)
    b_float = convert_to_float(b)

    # Compare and return appropriate value
    if a_float > b_float:
        return a
    elif b_float > a_float:
        return b
    else:
        return None

