def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, value)
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract the sorted values
    return [num for _, _, num in indexed_nums]

def get_max_triples(n):
    # Create the array a where a[i] = i * i - i + 1
    a = [i * i - i + 1 for i in range(1, n + 1)]

    # Count triples where sum is divisible by 3
    count = 0

    # Check all combinations where i < j < k
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1

    return count

def Strongest_Extension(class_name, extensions):
    def calculate_strength(extension):
        cap = sum(1 for c in extension if c.isupper())
        sm = sum(1 for c in extension if c.islower())
        return cap - sm

    strongest_ext = extensions[0]
    strongest_strength = calculate_strength(extensions[0])

    for ext in extensions[1:]:
        strength = calculate_strength(ext)
        if strength > strongest_strength:
            strongest_strength = strength
            strongest_ext = ext

    return f"{class_name}.{strongest_ext}"

def solve(s):
    """You are given a string s.
    if s[i] is a letter, reverse its case from lower to upper or vise versa, 
    otherwise keep it as it is.
    If the string contains no letters, reverse the string.
    The function should return the resulted string.
    Examples
    solve("1234") = "4321"
    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    """
    # Check if string contains any letters
    has_letters = any(char.isalpha() for char in s)

    if not has_letters:
        # If no letters, reverse the string
        return s[::-1]
    else:
        # If there are letters, reverse case of each letter
        result = ""
        for char in s:
            if char.isalpha():
                # Reverse case: lower to upper, upper to lower
                if char.islower():
                    result += char.upper()
                else:
                    result += char.lower()
            else:
                # Keep non-letters as they are
                result += char
        return result
